package com.blog.repository; import com.blog.entity.Post; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; public interface PostRepository extends JpaRepository<Post,Long> { @Query("select p from Post p where lower(p.title) like lower(concat('%',:keyword,'%')) or lower(p.content) like lower(concat('%',:keyword,'%'))") Page<Post> search(@Param("keyword") String keyword, Pageable pageable); Page<Post> findByCategoryId(Long categoryId, Pageable pageable); boolean existsByCategoryId(Long categoryId); }
